from typing import Optional

def distinct_chars(s: str) -> int:
    """Return the number of unique characters in s.

    Args:
        s: The input string.

    Returns:
        The cardinality of the set of characters in s.

    Examples:
        >>> distinct_chars("abca")
        3
        >>> distinct_chars("")
        0
    """
    return _walk(s, set())

def _walk(s: str, seen: set) -> int:
    if not s:
        return len(seen)
    seen.add(s[0])
    return _walk(s[1:], seen)

from typing import Any, Dict

def flatten_dict(d: Dict[str, Any], sep: str = ".") -> Dict[str, Any]:
    """Flatten nested dictionaries using a separator.

    Args:
        d: A dictionary possibly containing nested dictionaries.
        sep: Separator for joined keys.

    Returns:
        A new dictionary with a single level of depth.

    Examples:
        >>> flatten_dict({"a": {"b": 1, "c": {"d": 2}}})
        {'a.b': 1, 'a.c.d': 2}
        >>> flatten_dict({"x": 1})
        {'x': 1}
    """
    out: Dict[str, Any] = {}
    _walk(d, "", out, sep)
    return out

def _walk(d: Dict[str, Any], prefix: str, out: Dict[str, Any], sep: str) -> None:
    for key, value in d.items():
        full = f"{prefix}{sep}{key}" if prefix else str(key)
        if isinstance(value, dict):
            _walk(value, full, out, sep)
        else:
            out[full] = value

from typing import Optional

def nth_prime(n: int) -> int:
    """Return the n-th prime number (1-indexed).

    Args:
        n: A positive integer.

    Returns:
        The n-th prime.

    Raises:
        ValueError: If n is not positive.

    Examples:
        >>> nth_prime(1)
        2
        >>> nth_prime(6)
        13
    """
    if n <= 0:
        raise ValueError("n must be positive")
    return _find(1, n, 2)

def _find(current: int, target: int, candidate: int) -> int:
    if current == target:
        return candidate
    return _find(current + 1, target, _next_prime(candidate))

def _next_prime(candidate: int) -> int:
    n = candidate + 1
    while True:
        if _is_prime(n):
            return n
        n += 1

def _is_prime(x: int) -> bool:
    if x < 2:
        return False
    if x < 4:
        return True
    if x % 2 == 0:
        return False
    i = 3
    while i * i <= x:
        if x % i == 0:
            return False
        i += 2
    return True

from typing import List, Optional

def binary_search(sorted_list: List[int], target: int) -> int:
    """Find target in a sorted list using binary search.

    Args:
        sorted_list: A non-empty list sorted in ascending order.
        target: The value to find.

    Returns:
        Index of target if found, otherwise -1.

    Raises:
        ValueError: If sorted_list is empty.

    Examples:
        >>> binary_search([1, 3, 5, 7, 9], 7)
        3
        >>> binary_search([1, 3, 5, 7, 9], 4)
        -1
    """
    if not sorted_list:
        raise ValueError("sorted_list must be non-empty")
    return _search(sorted_list, target, 0, len(sorted_list) - 1)

def _search(a: List[int], target: int, lo: int, hi: int) -> int:
    if lo > hi:
        return -1
    mid = (lo + hi) // 2
    if a[mid] == target:
        return mid
    if a[mid] < target:
        return _search(a, target, mid + 1, hi)
    return _search(a, target, lo, mid - 1)

from typing import List, Union

Number = Union[int, float]

def evaluate(tokens: List[str]) -> Number:
    """Evaluate a fully parenthesized arithmetic expression.

    Args:
        tokens: A token list like ['(', '3', '+', '4', ')', '*', '5'].

    Returns:
        The numeric result of the expression.

    Raises:
        ValueError: If the token list is malformed.

    Examples:
        >>> evaluate(["(", "3", "+", "4", ")"])
        7
        >>> evaluate(["(", "2", "*", "(", "3", "+", "4", ")", ")"])
        14
    """
    pos = [0]
    result = _parse(tokens, pos)
    if pos[0] != len(tokens):
        raise ValueError("unexpected trailing tokens")
    return result

def _parse(tokens: List[str], pos: List[int]) -> Number:
    if pos[0] >= len(tokens):
        raise ValueError("unexpected end of expression")
    tok = tokens[pos[0]]
    pos[0] += 1
    if tok == "(":
        left = _parse(tokens, pos)
        op = tokens[pos[0]]
        pos[0] += 1
        right = _parse(tokens, pos)
        if tokens[pos[0]] != ")":
            raise ValueError("missing closing parenthesis")
        pos[0] += 1
        if op == "+":
            return left + right
        if op == "-":
            return left - right
        if op == "*":
            return left * right
        if op == "/":
            return left / right
        raise ValueError(f"unsupported operator {op!r}")
    return _number(tok)

def _number(tok: str) -> Number:
    try:
        return int(tok)
    except ValueError:
        return float(tok)

from typing import Optional

def valid_parens(s: str) -> bool:
    """Check whether s is a valid parenthesis sequence.

    Args:
        s: A string of '(' and ')'.

    Returns:
        True if the parentheses are balanced, False otherwise.

    Examples:
        >>> valid_parens("()()")
        True
        >>> valid_parens("())")
        False
        >>> valid_parens("")
        True
    """
    return _match(s, 0)

def _match(s: str, i: int) -> bool:
    if i == len(s):
        return True
    if s[i] == ")":
        return False
    return _find_close(s, i + 1, 1)

def _find_close(s: str, i: int, depth: int) -> bool:
    if i >= len(s):
        return False
    if s[i] == "(":
        return _find_close(s, i + 1, depth + 1)
    depth -= 1
    if depth == 0:
        return i + 1 == len(s) or _match(s, i + 1)
    return _find_close(s, i + 1, depth)

from typing import Callable, Any, Dict, Tuple
from functools import wraps

def memoize(func: Callable[..., Any]) -> Callable[..., Any]:
    """Memoize a function using a recursive descent into tuple arguments.

    Args:
        func: A pure function whose arguments are hashable (or tuples of hashables).

    Returns:
        A wrapped function with a shared cache.

    Examples:
        >>> @memoize
        ... def add(x: int, y: int) -> int:
        ...     return x + y
        >>> add(2, 3)
        5
        >>> add(2, 3)
        5
    """
    cache: Dict[Tuple[Any, ...], Any] = {}
    @wraps(func)
    def wrapper(*args: Any) -> Any:
        key = _to_key(args)
        if key not in cache:
            cache[key] = func(*args)
        return cache[key]
    wrapper.cache_clear = lambda: cache.clear()
    return wrapper

def _to_key(args: Tuple[Any, ...]) -> Tuple[Any, ...]:
    out = []
    for a in args:
        if isinstance(a, list):
            out.append(_to_key(tuple(a)))
        elif isinstance(a, dict):
            out.append(tuple(sorted((k, _to_key(v)) for k, v in a.items())))
        else:
            out.append(a)
    return tuple(out)

from typing import List, Optional

Board = List[List[int]]

def solve_sudoku(board: Board) -> Optional[Board]:
    """Solve a 9x9 sudoku board in-place using backtracking.

    Args:
        board: A 9x9 grid of integers where 0 denotes an empty cell.

    Returns:
        The solved board, or None if no solution exists.

    Examples:
        >>> b = [
        ...     [5, 3, 0, 0, 7, 0, 0, 0, 0],
        ...     [6, 0, 0, 1, 9, 5, 0, 0, 0],
        ...     [0, 9, 8, 0, 0, 0, 0, 6, 0],
        ... ]
        >>> solve_sudoku(b) is not None
        True
    """
    empty = _find_empty(board)
    if empty is None:
        return board
    row, col = empty
    for num in range(1, 10):
        if _is_safe(board, row, col, num):
            board[row][col] = num
            if solve_sudoku(board) is not None:
                return board
            board[row][col] = 0
    return None

def _find_empty(board: Board) -> Optional[tuple]:
    for r in range(9):
        for c in range(9):
            if board[r][c] == 0:
                return (r, c)
    return None

def _is_safe(board: Board, row: int, col: int, num: int) -> bool:
    if num in board[row]:
        return False
    for r in range(9):
        if board[r][col] == num:
            return False
    box_r, box_c = 3 * (row // 3), 3 * (col // 3)
    for r in range(box_r, box_r + 3):
        for c in range(box_c, box_c + 3):
            if board[r][c] == num:
                return False
    return True

from typing import List

Matrix = List[List[float]]

def determinant(matrix: Matrix) -> float:
    """Compute the determinant of a square matrix.

    Args:
        matrix: An n x n list of lists.

    Returns:
        The determinant as a float.

    Raises:
        ValueError: If matrix is not square.

    Examples:
        >>> determinant([[1, 2], [3, 4]])
        -2.0
        >>> determinant([[5]])
        5.0
    """
    n = len(matrix)
    if n == 0:
        return 1.0
    if any(len(row) != n for row in matrix):
        raise ValueError("matrix must be square")
    if n == 1:
        return float(matrix[0][0])
    if n == 2:
        return float(matrix[0][0] * matrix[1][1] - matrix[0][1] * matrix[1][0])
    total = 0.0
    for j in range(n):
        sub = [row[:j] + row[j + 1:] for row in matrix[1:]]
        total += ((-1) ** j) * matrix[0][j] * determinant(sub)
    return float(total)

from typing import List, Optional, Dict

def min_coins(coins: List[int], amount: int) -> int:
    """Compute the minimum coins to form amount.

    Args:
        coins: A list of distinct positive coin denominations.
        amount: A non-negative target amount.

    Returns:
        The minimum number of coins needed; -1 if impossible.

    Examples:
        >>> min_coins([1, 5, 10, 25], 41)
        4
        >>> min_coins([2], 3)
        -1
    """
    if amount < 0:
        raise ValueError("amount must be non-negative")
    memo: Dict[int, int] = {0: 0}
    return _solve(coins, amount, memo)

def _solve(coins: List[int], amount: int, memo: Dict[int, int]) -> int:
    if amount in memo:
        return memo[amount]
    if amount < 0:
        return -1
    best = -1
    for c in coins:
        sub = _solve(coins, amount - c, memo)
        if sub != -1:
            candidate = 1 + sub
            if best == -1 or candidate < best:
                best = candidate
    memo[amount] = best
    return best

from typing import List, Optional, Dict

def decode_ways(s: str) -> List[str]:
    """Decode a digit string into every possible letter sequence.

    Args:
        s: A non-empty string of digits.

    Returns:
        A list of decoded strings; each maps a partition of s into 1- or 2-digit codes.

    Raises:
        ValueError: If s contains non-digit characters.

    Examples:
        >>> sorted(decode_ways("12"))
        ['AB', 'L']
        >>> decode_ways("0")
        []
    """
    if not s:
        return []
    if any(not ch.isdigit() for ch in s):
        raise ValueError("s must contain only digits")
    memo: Dict[int, List[str]] = {}
    return _decode(s, 0, memo)

def _decode(s: str, i: int, memo: Dict[int, List[str]]) -> List[str]:
    if i in memo:
        return memo[i]
    if i == len(s):
        return [""]
    out: List[str] = []
    if s[i] != "0":
        out.extend(ch + rest for rest in _decode(s, i + 1, memo) for ch in [_letter(int(s[i]))])
    if i + 1 < len(s) and s[i] != "0" and int(s[i:i + 2]) <= 26:
        out.extend(ch + rest for rest in _decode(s, i + 2, memo) for ch in [_letter(int(s[i:i + 2]))])
    memo[i] = out
    return out

def _letter(value: int) -> str:
    return chr(ord("A") + value - 1)
